Change(genesis='66602cd0dec37d58d03eec9518ca805a7ac38ea912d2b0c366a0b67b4b9f50b6', deps=(), event=Decided(decision='editnotperl', at=datetime(2026, 11, 26, 0, 0, 0), actor='assistant', title='Multi-line edits use the edit tool, and multi-line content goes through the write tool', body="Do not edit code with a perl or sed substitution that holds dollar signs, braces or pipes. Do not put a heredoc inside another program's argument. If a scripted edit is unavoidable, pick a delimiter that is absent from the text, and check the result with grep and a diff stat. Chain a cleanup step that a commit depends on with and, and check it before adding files.", rationale='A replacement string interpolates variables and a missed terminator runs file text as commands.', supersedes=()))